    fn closure_map_any_program() -> (crate::core::NodeId, MirProgram) {
        canonical_program_with_main(
            r#"
func main() -> i32 {
    println(7)
    let seed_result = map_new()
    match seed_result {
        Ok(seed) => {
            let null_pair = map_get(seed, "none")
            drop(seed)
            let snapshot = fn() {
                let empty_result = map_new()
                match empty_result {
                    Ok(empty) => {
                        let root_result = map_set(empty, "key", "detached")
                        match root_result {
                            Ok(root) => {
                                let pair = map_get(root, "key")
                                drop(empty)
                                drop(root)
                                pair
                            },
                            Err(status) => {
                                drop(empty)
                                null_pair
                            },
                        }
                    },
                    Err(status) => { null_pair },
                }
            }
            let (found, payload) = snapshot()
            println(found)
            drop(payload)
            drop(null_pair)
            0
        },
        Err(status) => { status },
    }
}
"#,
        )
    }

    fn assert_closure_preflight_rejects_before_output(owner: &NodeId, program: &MirProgram) {
        let interpreter = MirReferenceInterpreter::new(program);
        let error = interpreter
            .execute_with_output(owner, &[])
            .expect_err("forged closure state must fail before reference execution");
        assert!(
            error.message.to_ascii_lowercase().contains("closure"),
            "{error:?}"
        );
        assert!(interpreter.captured_output().is_empty());
    }

    #[test]
    fn managed_any_identity_program_rechecks_call_and_instance_binding() {
        let source = r#"
func carry<T>(value: T) -> T { value }
func main() -> i32 {
    match map_new() {
        Ok(empty) => {
            match map_set(empty, "zero", 0) {
                Ok(root) => {
                    let pair = map_get(root, "zero")
                    drop(empty)
                    drop(root)
                    let found = pair.0
                    let payload = pair.1
                    let carried = carry(payload)
                    drop(pair)
                    drop(payload)
                    drop(carried)
                    if found { 0 } else { 0 }
                },
                Err(status) => {
                    drop(empty)
                    status
                },
            }
        },
        Err(status) => { status },
    }
}
"#;
        let (main, program) = canonical_program_with_main(source);
        let identity_id = program
            .instances
            .values()
            .find(|instance| instance.contract == MirGenericInstanceContract::ManagedAnyIdentity)
            .expect("ManagedAny identity instance")
            .id
            .clone();
        program
            .validate_managed_any_identity_instances()
            .expect("the Checker-sealed identity table and call boundary");

        let nested_any_type = program
            .functions
            .get(&main)
            .expect("main MIR")
            .values
            .values()
            .map(|value| value.ty.clone())
            .find(|ty| {
                matches!(
                    program.type_catalog.get(ty).map(|descriptor| &descriptor.layout),
                    Some(super::super::types::MirLayout::Tuple(elements))
                        if elements.iter().any(|element| program.type_catalog.contains_dynamic_or_managed_any(element))
                )
            })
            .expect("Map GetAny tuple with recursively nested ManagedAny");

        let mut nested_instance_argument = program.clone();
        nested_instance_argument
            .instances
            .get_mut(&identity_id)
            .expect("identity instance")
            .arguments = vec![nested_any_type.clone()];
        let errors = nested_instance_argument
            .validate_managed_any_identity_instances()
            .expect_err(
                "a recursively Any-bearing tuple is not the exact direct Any identity argument",
            );
        assert!(
            errors
                .iter()
                .any(|error| { error.contains("recursive DynamicAny/ManagedAny type argument") }),
            "{errors:?}"
        );

        let mut nested_call_argument = program.clone();
        let caller = nested_call_argument.functions.get_mut(&main).unwrap();
        let call = caller
            .blocks
            .values_mut()
            .flat_map(|block| &mut block.instructions)
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::Call { callee, .. }
                        if super::super::canonical_protocol_call_target(callee).as_ref()
                            == Some(&program.instances[&identity_id].function)
                )
            })
            .expect("carry call");
        let MirInstructionKind::Call { type_arguments, .. } = &mut call.kind else {
            unreachable!()
        };
        *type_arguments = vec![nested_any_type];
        let errors = nested_call_argument
            .validate_managed_any_identity_instances()
            .expect_err("a call cannot smuggle recursive Any through a composite type argument");
        assert!(
            errors.iter().any(|error| {
                error.contains("no exact identity/trap-cleanup")
                    || error.contains("recursive DynamicAny/ManagedAny type argument")
            }),
            "{errors:?}"
        );

        let mut missing_instance = program.clone();
        missing_instance.instances.remove(&identity_id);
        assert!(missing_instance
            .validate_managed_any_identity_instances()
            .is_err());

        let mut orphaned_seal = program.clone();
        orphaned_seal.instances.remove(&identity_id);
        let caller = orphaned_seal.functions.get_mut(&main).unwrap();
        let call = caller
            .blocks
            .values_mut()
            .flat_map(|block| &mut block.instructions)
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::Call { callee, .. }
                        if super::super::canonical_protocol_call_target(callee).as_ref()
                            == Some(&program.instances[&identity_id].function)
                )
            })
            .expect("carry call");
        let MirInstructionKind::Call { type_arguments, .. } = &mut call.kind else {
            unreachable!()
        };
        type_arguments.clear();
        assert!(
            MirProgram::with_type_catalog_and_instances(
                orphaned_seal.functions,
                orphaned_seal.type_catalog,
                orphaned_seal.instances,
            )
            .is_err(),
            "the canonical constructor rejects a deleted table row plus erased call type arguments"
        );

        let mut missing_arguments = program.clone();
        let caller = missing_arguments.functions.get_mut(&main).unwrap();
        let call = caller
            .blocks
            .values_mut()
            .flat_map(|block| &mut block.instructions)
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::Call { callee, .. }
                        if super::super::canonical_protocol_call_target(callee).as_ref()
                            == Some(&program.instances[&identity_id].function)
                )
            })
            .expect("carry call");
        let MirInstructionKind::Call { type_arguments, .. } = &mut call.kind else {
            unreachable!()
        };
        type_arguments.clear();
        assert!(missing_arguments
            .validate_managed_any_identity_instances()
            .is_err());

        let mut missing_argument = program.clone();
        let caller = missing_argument.functions.get_mut(&main).unwrap();
        let call = caller
            .blocks
            .values_mut()
            .flat_map(|block| &mut block.instructions)
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::Call { callee, .. }
                        if super::super::canonical_protocol_call_target(callee).as_ref()
                            == Some(&program.instances[&identity_id].function)
                )
            })
            .expect("carry call");
        let MirInstructionKind::Call { arguments, .. } = &mut call.kind else {
            unreachable!()
        };
        arguments.clear();
        assert!(missing_argument
            .validate_managed_any_identity_instances()
            .is_err());

        let mut missing_result = program.clone();
        let caller = missing_result.functions.get_mut(&main).unwrap();
        let call = caller
            .blocks
            .values_mut()
            .flat_map(|block| &mut block.instructions)
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::Call { callee, .. }
                        if super::super::canonical_protocol_call_target(callee).as_ref()
                            == Some(&program.instances[&identity_id].function)
                )
            })
            .expect("carry call");
        let MirInstructionKind::Call { result, .. } = &mut call.kind else {
            unreachable!()
        };
        *result = None;
        assert!(missing_result
            .validate_managed_any_identity_instances()
            .is_err());
    }

    #[test]
    fn managed_any_trap_cleanup_profiles_are_exactly_sealed_before_the_checked_trap() {
        for (source, expected_trap, expected_op) in [
            (
                include_str!(
                    "../../../tests/fixtures/mir_ordinary_map_any_get_cross_callee_division.mimi"
                ),
                super::super::MirManagedAnyTrapKind::DivisionByZeroI32,
                ResolvedBinaryOp::Divide,
            ),
            (
                include_str!(
                    "../../../tests/fixtures/mir_ordinary_map_any_get_cross_callee_overflow.mimi"
                ),
                super::super::MirManagedAnyTrapKind::SignedOverflowI32,
                ResolvedBinaryOp::Add,
            ),
        ] {
            let (_, program) = canonical_program_with_main(source);
            let instance = program
                .instances
                .values()
                .find(|instance| {
                    matches!(
                        instance.contract,
                        MirGenericInstanceContract::ManagedAnyTrapCleanup { .. }
                    )
                })
                .expect("one exact generic trap-cleanup specialization");
            assert_eq!(
                instance.contract,
                MirGenericInstanceContract::ManagedAnyTrapCleanup {
                    trap: expected_trap
                }
            );
            let function = &program.functions[&instance.function];
            let managed = program
                .type_catalog
                .validate_managed_any_identity_source_argument(&instance.arguments)
                .expect("raw source DynamicAny maps to canonical ManagedAny");
            assert_eq!(instance.arguments.len(), 1);
            assert_ne!(instance.arguments[0], managed);
            assert_eq!(function.parameters.len(), 1);
            assert_eq!(function.values[&function.parameters[0]].ty, managed);
            assert_eq!(
                function.result,
                crate::core::ir::primitive_type_id(crate::core::ir::PrimitiveType::I32)
            );
            let block = &function.blocks[&function.entry];
            assert_eq!(block.instructions.len(), 6);
            assert!(matches!(
                &block.instructions[4].kind,
                MirInstructionKind::ManagedAny {
                    source,
                    operation: super::super::MirManagedAnyOperation::Drop,
                    ..
                } if source == &function.parameters[0]
            ));
            assert!(matches!(
                &block.instructions[5].kind,
                MirInstructionKind::Binary {
                    op,
                    ..
                } if *op == expected_op
            ));
            let MirInstructionKind::Binary {
                result: trap_result,
                ..
            } = &block.instructions[5].kind
            else {
                unreachable!()
            };
            assert!(matches!(
                &block.terminator,
                super::super::MirTerminator::Return { value: Some(value) }
                    if value == trap_result
            ));
            program
                .type_catalog
                .validate_managed_any_trap_cleanup_instance(instance, function)
                .expect("private receipt binds exact body, instance, owner and trap");
            program
                .validate_managed_any_identity_instances()
                .expect("shared recursive Any gate admits the sealed direct trap profile");
            program
                .validate_managed_any_trap_cleanup_instances()
                .expect("instance/call boundary and callee cleanup are revalidated");
        }
    }

    #[test]
    fn managed_any_trap_cleanup_preflight_rejects_receipt_and_boundary_forgery() {
        let source = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_get_cross_callee_division.mimi"
        );
        let (_, program) = canonical_program_with_main(source);
        let instance = program
            .instances
            .values()
            .find(|instance| {
                matches!(
                    instance.contract,
                    MirGenericInstanceContract::ManagedAnyTrapCleanup { .. }
                )
            })
            .expect("trap cleanup instance")
            .clone();
        let main = program
            .functions
            .values()
            .find(|function| function.owner.0.ends_with("main"))
            .expect("main function")
            .owner
            .clone();

        let mut wrong_profile = instance.clone();
        wrong_profile.contract = MirGenericInstanceContract::ManagedAnyTrapCleanup {
            trap: super::super::MirManagedAnyTrapKind::SignedOverflowI32,
        };
        assert!(program
            .type_catalog
            .validate_managed_any_trap_cleanup_instance(
                &wrong_profile,
                &program.functions[&instance.function]
            )
            .is_err());

        let mut wrong_source_argument = instance.clone();
        wrong_source_argument.arguments[0] = managed_any_i32_string_v1_type_id();
        assert!(program
            .type_catalog
            .validate_managed_any_trap_cleanup_instance(
                &wrong_source_argument,
                &program.functions[&instance.function]
            )
            .is_err());

        let mut reordered_cleanup = program.clone();
        reordered_cleanup
            .functions
            .get_mut(&instance.function)
            .unwrap()
            .blocks
            .get_mut(&program.functions[&instance.function].entry)
            .unwrap()
            .instructions
            .swap(4, 5);
        assert!(reordered_cleanup
            .validate_managed_any_trap_cleanup_instances()
            .is_err());

        let mut forged_setup_identity = program.clone();
        forged_setup_identity
            .functions
            .get_mut(&instance.function)
            .unwrap()
            .blocks
            .get_mut(&program.functions[&instance.function].entry)
            .unwrap()
            .instructions[0]
            .id = super::super::MirInstructionId::new("inst:forged-initializer")
            .expect("valid adversarial instruction id");
        assert!(forged_setup_identity
            .validate_managed_any_trap_cleanup_instances()
            .is_err());

        let mut forged_trap_constant = program.clone();
        let initializer = &mut forged_trap_constant
            .functions
            .get_mut(&instance.function)
            .unwrap()
            .blocks
            .get_mut(&program.functions[&instance.function].entry)
            .unwrap()
            .instructions[0];
        let MirInstructionKind::Const { literal, .. } = &mut initializer.kind else {
            unreachable!()
        };
        *literal = crate::core::ir::ResolvedLiteral::Int(2);
        assert!(forged_trap_constant
            .validate_managed_any_trap_cleanup_instances()
            .is_err());

        let mut erased_call_argument = program.clone();
        let caller = erased_call_argument.functions.get_mut(&main).unwrap();
        let call = caller
            .blocks
            .values_mut()
            .flat_map(|block| &mut block.instructions)
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::Call { callee, .. }
                        if super::super::canonical_protocol_call_target(callee).as_ref()
                            == Some(&instance.function)
                )
            })
            .expect("fail(payload) call");
        let MirInstructionKind::Call { type_arguments, .. } = &mut call.kind else {
            unreachable!()
        };
        type_arguments.clear();
        assert!(erased_call_argument
            .validate_managed_any_trap_cleanup_instances()
            .is_err());

        let mut erased_instance = program.clone();
        erased_instance.instances.remove(&instance.id);
        let caller = erased_instance.functions.get_mut(&main).unwrap();
        let call = caller
            .blocks
            .values_mut()
            .flat_map(|block| &mut block.instructions)
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::Call { callee, .. }
                        if super::super::canonical_protocol_call_target(callee).as_ref()
                            == Some(&instance.function)
                )
            })
            .expect("fail(payload) call");
        let MirInstructionKind::Call { type_arguments, .. } = &mut call.kind else {
            unreachable!()
        };
        type_arguments.clear();
        assert!(erased_instance
            .validate_managed_any_identity_instances()
            .is_err());
        assert!(erased_instance
            .validate_managed_any_trap_cleanup_instances()
            .is_err());
    }

    #[test]
    fn checker_does_not_materialize_any_trap_cleanup_for_nearby_nontrapping_bodies() {
        let division = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_get_cross_callee_division.mimi"
        )
        .replace("let zero = 0", "let zero = 1");
        let overflow = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_get_cross_callee_overflow.mimi"
        )
        .replace("largest + 1", "largest + 2");
        for source in [division, overflow] {
            let tokens = crate::lexer::Lexer::new(&source)
                .tokenize()
                .expect("lex changed trap candidate");
            let file = crate::parser::Parser::new(tokens)
                .parse_file()
                .expect("parse changed trap candidate");
            let checked = crate::core::check_program(&file).expect("check source profile");
            assert!(
                MirProgram::from_checked_program(&checked).is_err(),
                "a generic ManagedAny specialization may not be inferred from a nearby body"
            );
        }
    }

    #[test]
    fn constructor_rejects_orphan_managed_any_identity_instance() {
        let source_with_identity_call = r#"
func carry<T>(value: T) -> T { value }
func main() -> i32 {
        match map_new() {
            Ok(empty) => {
            match map_set(empty, "zero", 0) {
                Ok(root) => {
                let pair = map_get(root, "zero")
                drop(empty)
                drop(root)
                let carried = carry(pair.1)
                drop(pair)
                drop(carried)
                0
            },
            Err(status) => {
                drop(empty)
                status
            },
            }
        },
        Err(status) => {
            status
        },
        }
}
"#;
        let source_without_identity_call = r#"
func main() -> i32 {
        match map_new() {
            Ok(empty) => {
            match map_set(empty, "zero", 0) {
                Ok(root) => {
                let pair = map_get(root, "zero")
                drop(empty)
                drop(root)
                drop(pair)
                0
            },
            Err(status) => {
                drop(empty)
                status
            },
            }
        },
        Err(status) => {
            status
        },
        }
}
"#;
        let (main_owner, main_program) = canonical_program_with_main(source_without_identity_call);
        let (_, identity_program) = canonical_program_with_main(source_with_identity_call);
        assert!(
            main_program
                .type_catalog
                .get(&super::super::types::ordinary_map_owned_any_v2_type_id())
                .is_none(),
            "an i32 Set/Get compatibility Map must not select the owner-v2 descriptor"
        );
        let instance = identity_program
            .instances
            .values()
            .find(|instance| instance.contract == MirGenericInstanceContract::ManagedAnyIdentity)
            .expect("one sealed carry<T> specialization")
            .clone();
        let identity_function = identity_program.functions[&instance.function].clone();
        let mut functions = main_program.functions.clone();
        assert!(functions.contains_key(&main_owner));
        functions.insert(identity_function.owner.clone(), identity_function);

        // The imported generic specialization's concrete ManagedAny ABI is
        // installed in the CheckedProgram catalog that materialized it. Use
        // that same catalog so this mutation reaches the intended orphaned
        // call-site check instead of failing earlier on a missing TypeDesc.
        let error = MirProgram::with_type_catalog_and_instances(
            functions,
            identity_program.type_catalog.clone(),
            BTreeMap::from([(instance.id.clone(), instance)]),
        )
        .expect_err("a valid specialization without a canonical caller must not enter MIR");
        assert!(error.iter().any(|error| {
            error.subject == "managed-any-identity"
                && error.message.contains("not bound to a call site")
        }));
    }

    fn canonical_map_any_owner_program() -> (NodeId, MirProgram) {
        canonical_program_with_main(
            r#"
func wide() -> i64 { 9 }
func main() -> i32 {
        let alternate = 7
        let first_result = map_new()
        match first_result {
            Ok(first) => {
            let updated_result = map_set(first, "answer", 42)
            match updated_result {
                Ok(updated) => {
                let size = map_size(updated)
                drop(updated)
                size
            },
            Err(status) => {
                drop(first)
                status
            },
            }
        },
        Err(status) => {
            status
        },
        }
}
"#,
        )
    }

    #[test]
    fn reference_replays_borrowed_ordinary_map_observers_with_detached_json() {
        let (owner, program) = canonical_program_with_main(
            r#"
func main() -> i32 {
        let source_result = map_new()
        match source_result {
            Ok(source) => {
            let root_result = map_set(source, "雪", "value")
            match root_result {
                Ok(root) => {
                let encoded = to_json(root)
                println(root)
                let size = map_size(root)
                drop(source)
                drop(root)
                println(encoded)
                size
            },
            Err(status) => {
                drop(source)
                status
            },
            }
        },
        Err(status) => {
            status
        },
        }
}
"#,
        );
        let receipts = program
            .ordinary_map_owner_lifecycle_observer_v1_receipts()
            .expect("complete Checker/MIR source and instruction census");
        assert_eq!(receipts.len(), 2);
        assert!(receipts
            .iter()
            .any(|receipt| receipt.builtin() == "to_json"));
        assert!(receipts
            .iter()
            .any(|receipt| receipt.builtin() == "println"));
        let route_receipt = program
            .ordinary_map_owner_lifecycle_observer_v1_route_receipt()
            .expect("isolated lifecycle observer route receipt");

        let interpreter = MirReferenceInterpreter::new(&program).with_route_receipt(&route_receipt);
        let observation = interpreter
            .execute_with_output(&owner, &[])
            .expect("reference execution borrows the live Map and later uses detached JSON");
        assert_eq!(observation.value, MirRuntimeValue::Int(1));
        assert_eq!(
            observation.output,
            "{\"雪\":\"value\"}\n{\"雪\":\"value\"}\n"
        );

        let mut forged = program.clone();
        let function = forged.functions.get_mut(&owner).expect("main MIR");
        let observer = function
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::OrdinaryMapOwnerLifecycleObserverPrintln { .. }
                )
            })
            .expect("println observer instruction");
        let MirInstructionKind::OrdinaryMapOwnerLifecycleObserverPrintln { callsite, .. } =
            &mut observer.kind
        else {
            unreachable!("selected println observer")
        };
        *callsite = NodeId("forged:observer-callsite".into());
        let forged_interpreter = MirReferenceInterpreter::new(&forged);
        let error = forged_interpreter
            .execute_with_output(&owner, &[])
            .expect_err("an edited observer instruction must fail before emitting output");
        assert!(error.message.contains("observer"), "{}", error.message);
        assert!(forged_interpreter.captured_output().is_empty());
    }

    #[test]
    fn reference_ordinary_map_observer_json_allocation_failures_are_e0800_and_atomic() {
        let (owner, program) = canonical_program_with_main(
            r#"
func main() -> i32 {
        println("before")
        let root_result = map_new()
        match root_result {
            Ok(root) => {
            let encoded = to_json(root)
            println(root)
            drop(root)
            drop(encoded)
            0
        },
        Err(status) => {
            status
        },
        }
}
"#,
        );
        let route_receipt = program
            .ordinary_map_owner_lifecycle_observer_v1_route_receipt()
            .expect("the exact source/MIR observer route receipt");

        // Stage 0 fails JSON serialization for to_json; stage 1 lets that
        // detached String succeed, then fails the borrowed println render.
        // Both failures must happen before the observer can append any bytes.
        for failure_stage in [0, 1] {
            let interpreter =
                MirReferenceInterpreter::new(&program).with_route_receipt(&route_receipt);
            let (error, output, attempts, triggered) =
                crate::runtime::with_ordinary_map_owned_get_allocation_failure_for_test(
                    failure_stage,
                    || {
                        let error = interpreter
                            .execute_with_output(&owner, &[])
                            .expect_err("injected observer JSON capacity failure is E0800");
                        (
                            error,
                            interpreter.captured_output(),
                            crate::runtime::ordinary_map_owned_get_allocation_attempts_for_test(),
                            crate::runtime::ordinary_map_owned_get_allocation_failure_triggered_for_test(),
                        )
                    },
                );

            assert!(error.message.contains("[E0800]"), "{error:?}");
            assert!(error
                .message
                .contains("ordinary Map lifecycle JSON observation failed"));
            assert_eq!(
                output, "before\n",
                "observer failure exposed partial stdout"
            );
            assert!(
                triggered,
                "injected observer allocation failure was not reached"
            );
            assert_eq!(attempts, failure_stage + 1);
        }
    }

    #[test]
    fn canonical_map_root_is_checker_receipted_and_reference_bytecode_agree() {
        let (owner, program) = canonical_map_any_owner_program();
        let function = program.functions().get(&owner).expect("main MIR");
        let operations = function
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .filter(|instruction| {
                matches!(
                    instruction.kind,
                    crate::core::mir::MirInstructionKind::MapRootNew { .. }
                        | crate::core::mir::MirInstructionKind::MapRootSet { .. }
                        | crate::core::mir::MirInstructionKind::MapRootRemove { .. }
                        | crate::core::mir::MirInstructionKind::MapRootSize { .. }
                        | crate::core::mir::MirInstructionKind::MapRootContains { .. }
                        | crate::core::mir::MirInstructionKind::MapRootDrop { .. }
                )
            })
            .count();
        assert_eq!(operations, 4);
        assert_eq!(function.ownership.checker_map_any_owners.len(), operations);
        assert!(program
            .type_catalog()
            .get(&crate::core::mir::types::map_any_owner_v1_type_id())
            .is_some());
        let canonical_function = function.canonical_text();
        let mut changed_receipt = function.clone();
        changed_receipt
            .ownership
            .checker_map_any_owners
            .iter_mut()
            .find(|receipt| receipt.kind == crate::core::MapAnyOwnerActionKind::Set)
            .expect("Set receipt")
            .root = "different:checker-root".into();
        assert_ne!(canonical_function, changed_receipt.canonical_text());

        let reference = MirReferenceInterpreter::new(&program)
            .execute_with_output(&owner, &[])
            .expect("reference executes checker-receipted MapAnyOwner v1 operations");
        assert_eq!(reference.value, MirRuntimeValue::Int(1));
        let bytecode = crate::interp::bytecode::mir::compile_mir_program(&program)
            .expect("AST-free bytecode lowers checker-receipted MapAnyOwner v1 operations");
        let mut vm = crate::interp::bytecode::BytecodeVM::new(bytecode);
        assert_eq!(
            vm.run_value().expect("bytecode execution"),
            crate::interp::Value::Int(1)
        );
        assert_eq!(vm.take_stdout(), reference.output);
        crate::verifier::validate_mir_capabilities(&program).expect(
            "whole-program capability gate admits the exact receipted MapAnyOwner v1 profile",
        );
    }

    #[test]
    fn canonical_map_root_size_contract_is_proven_from_receipted_keys() {
        let (owner, program) = canonical_program_with_main(
            r#"
func map_size_for(value: i32) -> i32 {
    ensures: result == 1
        let root_result = map_new()
        match root_result {
            Ok(root) => {
            let updated_result = map_set(root, "answer", value)
            match updated_result {
                Ok(updated) => {
                let size = map_size(updated)
                drop(updated)
                size
            },
            Err(status) => {
                drop(root)
                status
            },
            }
        },
        Err(status) => {
            status
        },
        }
}
func checked_map_size(value: i32) -> i32 {
    ensures: result == 1
    map_size_for(value)
}
func wrong_map_size() -> i32 {
    ensures: result == 1
        let first_result = map_new()
        match first_result {
            Ok(first) => {
            let alpha_result = map_set(first, "alpha", 1)
            match alpha_result {
                Ok(alpha) => {
                let beta_result = map_set(alpha, "beta", 2)
                match beta_result {
                    Ok(beta) => {
                    let size = map_size(beta)
                    drop(beta)
                    size
                },
                Err(status) => {
                    drop(alpha)
                    drop(first)
                    status
                },
                }
            },
            Err(status) => {
                drop(first)
                status
            },
            }
        },
        Err(status) => {
            status
        },
        }
}
func overflow_map_size() -> i32 {
    ensures: result == 1
        let root_result = map_new()
        match root_result {
            Ok(root) => {
            let updated_result = map_set(root, "overflow", 8)
            match updated_result {
                Ok(updated) => {
                let size = map_size(updated)
                drop(updated)
                size
            },
            Err(status) => {
                drop(root)
                status
            },
            }
        },
        Err(status) => {
            status
        },
        }
}
func main() -> i32 {
    ensures: result == 2
        let first_result = map_new()
        match first_result {
            Ok(first) => {
            let inserted_result = map_set(first, "answer", 41)
            match inserted_result {
                Ok(inserted) => {
                let overwritten_result = map_set(inserted, "answer", 42)
                match overwritten_result {
                    Ok(overwritten) => {
                    let with_unicode_result = map_set(overwritten, "雪", 7)
                    match with_unicode_result {
                        Ok(with_unicode) => {
                        let size = map_size(with_unicode)
                        drop(with_unicode)
                        size
                    },
                    Err(status) => {
                        drop(overwritten)
                        drop(inserted)
                        drop(first)
                        status
                    },
                    }
                },
                Err(status) => {
                    drop(inserted)
                    drop(first)
                    status
                },
                }
            },
            Err(status) => {
                drop(first)
                status
            },
            }
        },
        Err(status) => {
            status
        },
        }
}
"#,
        );
        crate::verifier::validate_mir_capabilities(&program)
            .expect("capability gate accepts the receipt-backed single-block profile");
        let results = crate::verifier::verify_mir(&program, "canonical-map-root-size".into())
            .expect("public MIR verifier result");
        let result = results
            .iter()
            .find(|result| result.func_name == owner.0)
            .expect("main ensures result");
        assert_eq!(
            result.status,
            crate::verifier::VerifStatus::Proven,
            "{}",
            result.message
        );
        let result = results
            .iter()
            .find(|result| result.func_name.ends_with("map_size_for"))
            .expect("symbolic MapRoot ensures result");
        assert_eq!(
            result.status,
            crate::verifier::VerifStatus::Proven,
            "{}",
            result.message
        );
        let result = results
            .iter()
            .find(|result| result.func_name.ends_with("checked_map_size"))
            .expect("wrapper ensures result");
        assert_eq!(
            result.status,
            crate::verifier::VerifStatus::Proven,
            "{}",
            result.message
        );
        let result = results
            .iter()
            .find(|result| result.func_name.ends_with("wrong_map_size"))
            .expect("wrong MapRoot size ensures result");
        assert_eq!(
            result.status,
            crate::verifier::VerifStatus::Disproven,
            "{}",
            result.message
        );

        let mut forged_receipt = program.clone();
        forged_receipt
            .functions
            .get_mut(&owner)
            .expect("main MIR")
            .ownership
            .checker_map_any_owners
            .iter_mut()
            .find(|receipt| receipt.kind == crate::core::MapAnyOwnerActionKind::Set)
            .expect("Set receipt")
            .key = Some("forged-key".into());
        let capability_errors = crate::verifier::validate_mir_capabilities(&forged_receipt)
            .expect_err("the capability gate must recheck the independent MapAnyOwner v1 receipt");
        assert!(capability_errors.iter().any(|error| {
            error.contains("canonical MIR structural preflight rejected")
                && error.contains(
                    "MapRoot operation disagrees with its private Checker root/type/key receipt",
                )
        }));
        let verifier_result = crate::verifier::verify_mir(
            &forged_receipt,
            "canonical-map-root-forged-receipt".into(),
        )
        .expect("public verifier reports a trusted-subset rejection");
        let verifier_result = verifier_result
            .iter()
            .find(|result| result.func_name == owner.0)
            .expect("main verifier result");
        assert_eq!(
            verifier_result.status,
            crate::verifier::VerifStatus::NotInTrustedSubset
        );
        assert!(verifier_result
            .message
            .contains("MapAnyOwner v1 verifier receipt/shape rejected"));

        let mut overflowing = program.clone();
        let overflow_owner = overflowing
            .functions
            .keys()
            .find(|owner| owner.0.ends_with("overflow_map_size"))
            .expect("overflow MapRoot function")
            .clone();
        let overflow_function = overflowing
            .functions
            .get_mut(&overflow_owner)
            .expect("overflow MapRoot function");
        let set_value = overflow_function
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .find_map(|instruction| match &instruction.kind {
                MirInstructionKind::MapRootSet { value, .. } => Some(value.clone()),
                _ => None,
            })
            .expect("MapRoot Set value");
        let constant = overflow_function
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::Const { result, .. } if result == &set_value
                )
            })
            .expect("MapRoot Set scalar constant");
        let MirInstructionKind::Const {
            literal: crate::core::ir::ResolvedLiteral::Int(literal),
            ..
        } = &mut constant.kind
        else {
            panic!("MapRoot Set scalar must be an integer literal");
        };
        *literal = i64::from(i32::MAX) + 1;
        let verifier_result =
            crate::verifier::verify_mir(&overflowing, "canonical-map-root-set-overflow".into())
                .expect("public verifier reports the reachable E0802 trap");
        let verifier_result = verifier_result
            .iter()
            .find(|result| result.func_name == overflow_owner.0)
            .expect("main verifier result");
        assert_eq!(
            verifier_result.status,
            crate::verifier::VerifStatus::Disproven,
            "{}",
            verifier_result.message
        );
        assert!(verifier_result.message.contains("E0802"));
    }

    #[test]
