    #[test]
    fn canonical_map_root_forged_i32_value_keeps_the_overflow_boundary() {
        let (owner, program) = canonical_map_any_owner_program();
        let mut forged = program.clone();
        let function = forged.functions.get_mut(&owner).expect("main MIR");
        let value = function
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .find_map(|instruction| match &instruction.kind {
                MirInstructionKind::MapRootSet { value, .. } => Some(value.clone()),
                _ => None,
            })
            .expect("MapRoot Set scalar");
        let constant = function
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::Const { result, .. } if result == &value
                )
            })
            .expect("MapRoot Set scalar constant");
        let MirInstructionKind::Const {
            literal: crate::core::ir::ResolvedLiteral::Int(literal),
            ..
        } = &mut constant.kind
        else {
            panic!("MapRoot Set scalar must be an integer literal");
        };
        *literal = i64::from(i32::MAX) + 1;

        let reference_error = MirReferenceInterpreter::new(&forged)
            .execute_with_output(&owner, &[])
            .expect_err("reference runtime must reject an out-of-range MapRoot scalar");
        assert!(reference_error.message.contains("E0802"));
        assert!(reference_error
            .message
            .contains("MapRoot.set value overflows i32"));

        match crate::interp::bytecode::mir::compile_mir_program(&forged) {
            Ok(bytecode) => {
                let bytecode_error = crate::interp::bytecode::BytecodeVM::new(bytecode)
                    .run_value()
                    .expect_err("bytecode runtime must reject the same forged scalar");
                assert_eq!(bytecode_error.code(), "E0802");
                assert!(bytecode_error
                    .message()
                    .contains("MapAnyOwner v1 set value overflows i32"));
            }
            Err(errors) => {
                assert!(errors.iter().any(|error| {
                    error.message.contains("i32") || error.message.contains("range")
                }))
            }
        }
    }

    #[test]
    fn canonical_map_root_gate_rejects_missing_forged_and_mismatched_receipts() {
        let (owner, program) = canonical_map_any_owner_program();

        let mut missing_functions = program.functions().clone();
        missing_functions
            .get_mut(&owner)
            .expect("main MIR")
            .ownership
            .checker_map_any_owners
            .clear();
        let missing =
            MirProgram::with_type_catalog(missing_functions, program.type_catalog().clone())
                .expect_err(
                    "missing independent MapAnyOwner v1 receipts must fail before consumers",
                );
        assert!(missing.iter().any(|error| {
            error
                .message
                .contains("MapAnyOwner v1 TypeDesc has no independent Checker receipt")
        }));

        let mut forged_functions = program.functions().clone();
        let function = forged_functions.get_mut(&owner).expect("main MIR");
        let set = function
            .ownership
            .checker_map_any_owners
            .iter_mut()
            .find(|receipt| receipt.kind == crate::core::MapAnyOwnerActionKind::Set)
            .expect("Set receipt");
        set.source = Some("forged:source-root".into());
        let forged =
            MirProgram::with_type_catalog(forged_functions, program.type_catalog().clone())
                .expect_err("forged MapAnyOwner v1 source identity must fail before consumers");
        assert!(forged.iter().any(|error| {
            error
                .message
                .contains("MapRoot Set source resource identity does not match")
        }));

        let mut rewritten_identity_functions = program.functions().clone();
        let function = rewritten_identity_functions
            .get_mut(&owner)
            .expect("main MIR");
        for receipt in &mut function.ownership.checker_map_any_owners {
            match receipt.kind {
                crate::core::MapAnyOwnerActionKind::New => {
                    receipt.root = "forged:root:new".into();
                }
                crate::core::MapAnyOwnerActionKind::Set => {
                    receipt.root = "forged:root:set".into();
                    receipt.source = Some("forged:root:new".into());
                }
                crate::core::MapAnyOwnerActionKind::Remove => {
                    receipt.root = "forged:root:remove".into();
                    receipt.source = Some("forged:root:set".into());
                }
                crate::core::MapAnyOwnerActionKind::Size
                | crate::core::MapAnyOwnerActionKind::Contains
                | crate::core::MapAnyOwnerActionKind::Drop => {
                    receipt.root = "forged:root:set".into();
                }
            }
        }
        let rewritten_identity = MirProgram::with_type_catalog(
            rewritten_identity_functions,
            program.type_catalog().clone(),
        )
        .expect_err("a coherently rewritten MapAnyOwner v1 identity chain must be rejected");
        assert!(rewritten_identity.iter().any(|error| {
            error
                .message
                .contains("invalid namespaced root/local identity")
        }));

        let mut result_functions = program.functions().clone();
        let function = result_functions.get_mut(&owner).expect("main MIR");
        let (old_result, result_type) = function
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .find_map(|instruction| match &instruction.kind {
                crate::core::mir::MirInstructionKind::MapRootSize { result, .. } => Some((
                    result.clone(),
                    function.values.get(result).expect("size result").ty.clone(),
                )),
                _ => None,
            })
            .expect("MapRoot Size instruction");
        let forged_result = super::MirValueId::new("value:forged_map_size").expect("MIR value id");
        function.values.insert(
            forged_result.clone(),
            super::super::MirValue {
                id: forged_result.clone(),
                ty: result_type,
            },
        );
        let mut changed = false;
        for instruction in function
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
        {
            if let crate::core::mir::MirInstructionKind::MapRootSize { result, .. } =
                &mut instruction.kind
            {
                assert_eq!(result, &old_result);
                *result = forged_result.clone();
                changed = true;
            }
        }
        assert!(changed);
        let mismatched_result =
            MirProgram::with_type_catalog(result_functions, program.type_catalog().clone())
                .expect_err("unreceipted MapRoot Size result must fail before consumers");
        assert!(mismatched_result.iter().any(|error| {
            error
                .message
                .contains("MapRoot operation disagrees with its private Checker")
        }));

        let mut value_functions = program.functions().clone();
        let function = value_functions.get_mut(&owner).expect("main MIR");
        let alternate_value = function
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .find_map(|instruction| match &instruction.kind {
                crate::core::mir::MirInstructionKind::Const {
                    result,
                    literal: crate::core::ir::ResolvedLiteral::Int(7),
                } => Some(result.clone()),
                _ => None,
            })
            .expect("earlier alternate i32 value");
        let mut changed = false;
        for instruction in function
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
        {
            if let crate::core::mir::MirInstructionKind::MapRootSet { value, .. } =
                &mut instruction.kind
            {
                *value = alternate_value.clone();
                changed = true;
            }
        }
        assert!(changed);
        let mismatched_value =
            MirProgram::with_type_catalog(value_functions, program.type_catalog().clone())
                .expect_err("unreceipted MapRoot Set value must fail before consumers");
        assert!(mismatched_value.iter().any(|error| {
            error
                .message
                .contains("MapRoot operation disagrees with its private Checker")
        }));

        let mut wrong_scalar_functions = program.functions().clone();
        let function = wrong_scalar_functions.get_mut(&owner).expect("main MIR");
        let set_value = function
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .find_map(|instruction| match &instruction.kind {
                crate::core::mir::MirInstructionKind::MapRootSet { value, .. } => {
                    Some(value.clone())
                }
                _ => None,
            })
            .expect("MapRoot Set value");
        let i64_type = program
            .type_catalog()
            .iter()
            .find_map(|(id, descriptor)| {
                (descriptor.kind
                    == crate::core::mir::types::MirTypeKind::Primitive(
                        crate::core::PrimitiveType::I64,
                    ))
                .then(|| id.clone())
            })
            .expect("canonical i64 TypeDesc");
        function
            .values
            .get_mut(&set_value)
            .expect("Set scalar value")
            .ty = i64_type;
        let wrong_scalar =
            MirProgram::with_type_catalog(wrong_scalar_functions, program.type_catalog().clone())
                .expect_err("MapRoot Set must reject a non-i32 scalar value");
        assert!(wrong_scalar.iter().any(|error| {
            error
                .message
                .contains("MapRoot operation disagrees with its private Checker")
        }));

        let mut forged_payload_type_functions = program.functions().clone();
        let function = forged_payload_type_functions
            .get_mut(&owner)
            .expect("main MIR");
        let i64_type = program
            .type_catalog()
            .iter()
            .find_map(|(id, descriptor)| {
                (descriptor.kind
                    == crate::core::mir::types::MirTypeKind::Primitive(
                        crate::core::PrimitiveType::I64,
                    ))
                .then(|| id.clone())
            })
            .expect("canonical i64 TypeDesc");
        function
            .ownership
            .checker_map_any_owners
            .iter_mut()
            .find(|receipt| receipt.kind == crate::core::MapAnyOwnerActionKind::Set)
            .expect("Set receipt")
            .value_type = Some(i64_type);
        let forged_payload_type = MirProgram::with_type_catalog(
            forged_payload_type_functions,
            program.type_catalog().clone(),
        )
        .expect_err("a forged MapRoot payload TypeDesc must fail before consumers");
        assert!(forged_payload_type.iter().any(|error| {
            error
                .message
                .contains("MapRoot operation disagrees with its private Checker")
        }));

        let mut escaping_functions = program.functions().clone();
        let function = escaping_functions.get_mut(&owner).expect("main MIR");
        let root = function
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .find_map(|instruction| match &instruction.kind {
                crate::core::mir::MirInstructionKind::MapRootSize { root, .. } => {
                    Some(root.clone())
                }
                _ => None,
            })
            .expect("MapRoot size root");
        let entry = function.entry.clone();
        function
            .blocks
            .get_mut(&entry)
            .expect("entry block")
            .instructions
            .push(super::MirInstruction {
                id: super::MirInstructionId::new("inst:forged_map_root_escape")
                    .expect("instruction id"),
                kind: crate::core::mir::MirInstructionKind::Call {
                    result: None,
                    callee: crate::core::ir::ResolvedCallee::Function(NodeId(
                        "function:discard_map_root".into(),
                    )),
                    type_arguments: Vec::new(),
                    arguments: vec![root],
                    effect_receipts: Vec::new(),
                    variant_call_contract: None,
                },
            });
        let escaping =
            MirProgram::with_type_catalog(escaping_functions, program.type_catalog().clone())
                .expect_err("a generic MIR call must not receive a MapRoot alias");
        assert!(escaping.iter().any(|error| {
            error
                .message
                .contains("MapRoot local is used outside its dedicated Checker-receipted operation")
        }));

        let mut branching_functions = program.functions().clone();
        let function = branching_functions.get_mut(&owner).expect("main MIR");
        let entry = function.entry.clone();
        let drop_block_id =
            super::MirBlockId::new("block:zz_map_root_drop").expect("drop block id");
        let skip_block_id =
            super::MirBlockId::new("block:zz_map_root_skip").expect("skip block id");
        let (drop_instruction, return_value) = {
            let block = function.blocks.get_mut(&entry).expect("entry block");
            let drop_index = block
                .instructions
                .iter()
                .position(|instruction| {
                    matches!(
                        instruction.kind,
                        crate::core::mir::MirInstructionKind::MapRootDrop { .. }
                    )
                })
                .expect("MapRoot drop instruction");
            let drop_instruction = block.instructions.remove(drop_index);
            let crate::core::mir::MirTerminator::Return { value: Some(value) } = &block.terminator
            else {
                panic!("scalar result return expected")
            };
            (drop_instruction, value.clone())
        };
        let condition =
            super::MirValueId::new("value:forged_map_root_branch").expect("branch condition id");
        let bool_type = program
            .type_catalog()
            .iter()
            .find_map(|(id, descriptor)| {
                (descriptor.kind
                    == crate::core::mir::types::MirTypeKind::Primitive(
                        crate::core::PrimitiveType::Bool,
                    ))
                .then(|| id.clone())
            })
            .expect("canonical bool TypeDesc");
        function.values.insert(
            condition.clone(),
            super::super::MirValue {
                id: condition.clone(),
                ty: bool_type,
            },
        );
        function
            .blocks
            .get_mut(&entry)
            .expect("entry block")
            .instructions
            .push(super::MirInstruction {
                id: super::MirInstructionId::new("inst:forged_map_root_branch_condition")
                    .expect("instruction id"),
                kind: crate::core::mir::MirInstructionKind::Const {
                    result: condition.clone(),
                    literal: crate::core::ir::ResolvedLiteral::Bool(true),
                },
            });
        function
            .blocks
            .get_mut(&entry)
            .expect("entry block")
            .terminator = crate::core::mir::MirTerminator::Branch {
            condition,
            then_edge: super::super::MirEdgeId::new("edge:map_root_drop").expect("drop edge id"),
            then_target: drop_block_id.clone(),
            then_arguments: Vec::new(),
            else_edge: super::super::MirEdgeId::new("edge:map_root_skip").expect("skip edge id"),
            else_target: skip_block_id.clone(),
            else_arguments: Vec::new(),
        };
        function.blocks.insert(
            drop_block_id.clone(),
            super::super::MirBlock {
                id: drop_block_id,
                parameters: Vec::new(),
                instructions: vec![drop_instruction],
                terminator: crate::core::mir::MirTerminator::Return {
                    value: Some(return_value.clone()),
                },
            },
        );
        function.blocks.insert(
            skip_block_id.clone(),
            super::super::MirBlock {
                id: skip_block_id,
                parameters: Vec::new(),
                instructions: Vec::new(),
                terminator: crate::core::mir::MirTerminator::Return {
                    value: Some(return_value),
                },
            },
        );
        let branch_around_drop =
            MirProgram::with_type_catalog(branching_functions, program.type_catalog().clone())
                .expect_err("every MapRoot path must discharge its root obligation");
        assert!(branch_around_drop
            .iter()
            .any(|error| { error.message.contains("single-block, return-only profile") }));
    }

    #[test]
    fn canonical_map_root_contains_receipt_rejects_forgery_and_wrong_result_abi() {
        let (_, program) = canonical_program_with_main(include_str!(
            "../../../tests/real_world/map_root_static_contains.mimi"
        ));
        let owner = program
            .functions()
            .keys()
            .find(|owner| owner.0.ends_with("main"))
            .expect("main MIR")
            .clone();

        let mut forged_key_functions = program.functions().clone();
        let function = forged_key_functions.get_mut(&owner).expect("main MIR");
        let receipt = function
            .ownership
            .checker_map_any_owners
            .iter_mut()
            .find(|receipt| receipt.kind == crate::core::MapAnyOwnerActionKind::Contains)
            .expect("Contains receipt");
        receipt.key = Some("forged-key".into());
        let forged_key =
            MirProgram::with_type_catalog(forged_key_functions, program.type_catalog().clone())
                .expect_err("forged Contains key receipt must fail before consumers");
        assert!(forged_key
            .iter()
            .any(|error| error.message.contains("MapRoot operation disagrees")));

        let mut missing_functions = program.functions().clone();
        let function = missing_functions.get_mut(&owner).expect("main MIR");
        function
            .ownership
            .checker_map_any_owners
            .retain(|receipt| receipt.kind != crate::core::MapAnyOwnerActionKind::Contains);
        let missing =
            MirProgram::with_type_catalog(missing_functions, program.type_catalog().clone())
                .expect_err("missing Contains receipt must fail before consumers");
        assert!(missing
            .iter()
            .any(|error| { error.message.contains("MapRoot checker receipt count") }));

        let mut forged_instruction_functions = program.functions().clone();
        let function = forged_instruction_functions
            .get_mut(&owner)
            .expect("main MIR");
        let contains = function
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::MapRootContains { .. }
                )
            })
            .expect("Contains instruction");
        let MirInstructionKind::MapRootContains { key, .. } = &mut contains.kind else {
            unreachable!("located Contains instruction")
        };
        *key = "different-key".into();
        let forged_instruction = MirProgram::with_type_catalog(
            forged_instruction_functions,
            program.type_catalog().clone(),
        )
        .expect_err("instruction key cannot diverge from receipt key");
        assert!(forged_instruction
            .iter()
            .any(|error| error.message.contains("MapRoot operation disagrees")));

        let mut forged_root_functions = program.functions().clone();
        let function = forged_root_functions.get_mut(&owner).expect("main MIR");
        let contains_root = function
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .find_map(|instruction| match &instruction.kind {
                MirInstructionKind::MapRootContains { root, .. } => Some(root.clone()),
                _ => None,
            })
            .expect("Contains root");
        let alternate_root = function
            .values
            .values()
            .find(|value| {
                value.ty == crate::core::mir::types::map_any_owner_v1_type_id()
                    && value.id != contains_root
            })
            .expect("another receipted MapRoot value")
            .id
            .clone();
        let contains = function
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::MapRootContains { root, .. } if root == &contains_root
                )
            })
            .expect("Contains instruction");
        let MirInstructionKind::MapRootContains { root, .. } = &mut contains.kind else {
            unreachable!("located Contains instruction")
        };
        *root = alternate_root;
        let forged_root =
            MirProgram::with_type_catalog(forged_root_functions, program.type_catalog().clone())
                .expect_err("Contains cannot cite a different live root");
        assert!(forged_root
            .iter()
            .any(|error| error.message.contains("MapRoot operation disagrees")));

        let mut wrong_result_type_functions = program.functions().clone();
        let function = wrong_result_type_functions
            .get_mut(&owner)
            .expect("main MIR");
        let contains_result = function
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .find_map(|instruction| match &instruction.kind {
                MirInstructionKind::MapRootContains { result, .. } => Some(result.clone()),
                _ => None,
            })
            .expect("Contains result");
        let i32_type = program
            .type_catalog()
            .iter()
            .find_map(|(id, descriptor)| {
                (descriptor.kind
                    == crate::core::mir::types::MirTypeKind::Primitive(
                        crate::core::PrimitiveType::I32,
                    ))
                .then(|| id.clone())
            })
            .expect("canonical i32 TypeDesc");
        function
            .values
            .get_mut(&contains_result)
            .expect("Contains result value")
            .ty = i32_type;
        let forged_function = wrong_result_type_functions
            .get(&owner)
            .expect("forged Contains MIR")
            .clone();
        let invalid_constructor = MirProgram::with_type_catalog(
            wrong_result_type_functions,
            program.type_catalog().clone(),
        )
        .expect_err("MIR constructor must reject a non-bool Contains result TypeDesc");
        assert!(invalid_constructor.iter().any(|error| {
            error.message.contains("MapRoot operation disagrees")
                || error.message.contains("canonical bool TypeDesc")
        }));

        let mut forged_program = program.clone();
        forged_program.replace_function_for_test_only(forged_function);
        let bytecode_error = crate::interp::bytecode::compile_mir_program(&forged_program)
            .expect_err("direct bytecode adapter must revalidate a forged Contains result ABI");
        assert!(bytecode_error.iter().any(|error| {
            error.message.contains("canonical MIR validation failed")
                && error.message.contains("MapRoot operation disagrees")
        }));
    }

    #[test]
    fn canonical_map_any_owner_gate_rejects_unclaimed_or_noncanonical_descriptors() {
        let (root_owner, root_program) = canonical_map_any_owner_program();
        let (_, scalar_program) = canonical_program_with_main("func main() -> i32 { 42 }");
        let root_id = crate::core::mir::types::map_any_owner_v1_type_id();
        let descriptor = root_program
            .type_catalog()
            .get(&root_id)
            .expect("checker MapAnyOwner v1 descriptor")
            .clone();

        let mut extra_root_functions = root_program.functions().clone();
        let function = extra_root_functions.get_mut(&root_owner).expect("main MIR");
        let extra_root =
            super::MirValueId::new("param:unclaimed_map_any_owner").expect("MIR value id");
        function.values.insert(
            extra_root.clone(),
            super::super::MirValue {
                id: extra_root.clone(),
                ty: root_id.clone(),
            },
        );
        function.parameters.push(extra_root);
        let extra_root_error = MirProgram::with_type_catalog(
            extra_root_functions,
            root_program.type_catalog().clone(),
        )
        .expect_err("unreceipted MapAnyOwner v1 parameter must be rejected");
        assert!(extra_root_error.iter().any(|error| {
            error
                .message
                .contains("MapRoot values must match exactly the Checker-receipted local roots")
        }));

        let mut unclaimed_catalog = scalar_program.type_catalog().clone();
        unclaimed_catalog.replace_for_test_only(root_id.clone(), descriptor.clone());
        let unclaimed =
            MirProgram::with_type_catalog(scalar_program.functions().clone(), unclaimed_catalog)
                .expect(
                "MIR constructor preserves an unused MapAnyOwner descriptor for the consumer gate",
            );
        let unclaimed_errors = crate::verifier::validate_mir_capabilities(&unclaimed)
            .expect_err("an unused MapAnyOwner descriptor must not authorize a forged operation");
        assert!(unclaimed_errors
            .iter()
            .any(|error| error.contains("MapAnyOwner v1 TypeDesc presence")));

        let mut mislabeled_catalog = scalar_program.type_catalog().clone();
        let i32_descriptor = mislabeled_catalog
            .iter()
            .find_map(|(_, descriptor)| {
                (descriptor.kind
                    == crate::core::mir::types::MirTypeKind::Primitive(
                        crate::core::PrimitiveType::I32,
                    ))
                .then(|| descriptor.clone())
            })
            .expect("canonical i32 descriptor");
        mislabeled_catalog.replace_for_test_only(root_id.clone(), i32_descriptor);
        let mut mislabeled_functions = scalar_program.functions().clone();
        let function = mislabeled_functions
            .get_mut(&NodeId("function:main".into()))
            .expect("main MIR");
        let forged_parameter =
            super::MirValueId::new("param:forged_map_any_owner_type").expect("MIR value id");
        function.values.insert(
            forged_parameter.clone(),
            super::super::MirValue {
                id: forged_parameter.clone(),
                ty: root_id.clone(),
            },
        );
        function.parameters.push(forged_parameter);
        let mislabeled = MirProgram::with_type_catalog(mislabeled_functions, mislabeled_catalog)
            .expect_err(
                "canonical MapAnyOwner v1 identity with a different TypeDesc must be rejected",
            );
        assert!(mislabeled.iter().any(|error| {
            error.message.contains(
                "canonical MapAnyOwner v1 TypeDesc identity has a non-MapAnyOwner descriptor",
            ) || error
                .message
                .contains("MapAnyOwner v1 TypeDesc has no independent Checker receipt")
        }));

        let mut forged_catalog = root_program.type_catalog().clone();
        let forged_id = crate::core::ResolvedTypeId::synthetic("forged:MapAnyOwnerV1");
        forged_catalog.replace_for_test_only(forged_id.clone(), descriptor.clone());
        let mut forged_functions = root_program.functions().clone();
        let function = forged_functions.get_mut(&root_owner).expect("main MIR");
        let forged_parameter =
            super::MirValueId::new("param:forged_map_any_owner_identity").expect("MIR value id");
        function.values.insert(
            forged_parameter.clone(),
            super::super::MirValue {
                id: forged_parameter.clone(),
                ty: forged_id,
            },
        );
        function.parameters.push(forged_parameter);
        function
            .parameter_permissions
            .as_mut()
            .expect("lowered function retains checker parameter permissions")
            .push(None);
        let forged = MirProgram::with_type_catalog(forged_functions, forged_catalog)
            .expect_err("noncanonical MapAnyOwner v1 TypeDesc identity must fail before consumers");
        assert!(
            forged.iter().any(|error| {
                error
                    .message
                    .contains("MapAnyOwner value uses a non-canonical v1 TypeDesc identity")
            }),
            "MIR constructor errors: {forged:#?}"
        );

        let mut malformed_catalog = root_program.type_catalog().clone();
        let mut malformed_descriptor = descriptor.clone();
        malformed_descriptor.ownership = crate::core::mir::types::MirOwnership::Copy;
        malformed_catalog.replace_for_test_only(root_id.clone(), malformed_descriptor);
        let malformed =
            MirProgram::with_type_catalog(root_program.functions().clone(), malformed_catalog)
                .expect_err("forged MapRoot ABI/ownership metadata must be rejected");
        assert!(malformed.iter().any(|error| {
            error
                .message
                .contains("MapAnyOwner v1 TypeDesc has an inconsistent ABI/ownership/glue contract")
        }));

        let mut malformed_for_capability = root_program.clone();
        let mut malformed_descriptor = descriptor.clone();
        malformed_descriptor.ownership = crate::core::mir::types::MirOwnership::Copy;
        malformed_for_capability
            .type_catalog
            .replace_for_test_only(root_id, malformed_descriptor);
        let capability_errors =
            crate::verifier::validate_mir_capabilities(&malformed_for_capability).expect_err(
                "verifier capability must independently reject a forged MapAnyOwner v1 descriptor",
            );
        assert!(capability_errors.iter().any(|error| {
            error
                .contains("MapAnyOwner v1 TypeDesc has an inconsistent ABI/ownership/glue contract")
        }));
    }

