    #[test]
    fn concrete_scalar_generic_identity_is_an_executable_mir_instance() {
        let source =
            "func identity<T>(value: T) -> T { value }\nfunc main() -> i32 { identity(41) }";
        let tokens = Lexer::new(source).tokenize().expect("lex");
        let file = Parser::new(tokens).parse_file().expect("parse");
        let checked = crate::core::check_program(&file).expect("check");
        let program = MirProgram::from_checked_program(&checked)
            .expect("a supported concrete generic call must materialize in MIR");
        assert_eq!(program.instances().len(), 1);
        let instance = program
            .instances()
            .values()
            .next()
            .expect("identity instance");
        assert_eq!(instance.template, NodeId("function:identity".into()));
        assert!(program.functions().contains_key(&instance.function));
        let main = program
            .functions()
            .get(&NodeId("function:main".into()))
            .expect("main MIR function");
        let (callee, type_arguments) = main
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .find_map(|instruction| match &instruction.kind {
                crate::core::mir::MirInstructionKind::Call {
                    callee,
                    type_arguments,
                    ..
                } => Some((callee, type_arguments)),
                _ => None,
            })
            .expect("identity call");
        assert_eq!(
            callee,
            &crate::core::ir::ResolvedCallee::Function(instance.function.clone())
        );
        assert_eq!(type_arguments, &instance.arguments);

        let value = MirReferenceInterpreter::new(&program)
            .execute(&NodeId("function:main".into()), &[])
            .expect("reference execution");
        assert_eq!(value, MirRuntimeValue::Int(41));
    }

    #[test]
    fn scalar_generic_identity_island_rejects_forged_out_of_range_i32_literal() {
        let source =
            "func identity<T>(value: T) -> T { value }\nfunc main() -> i32 { identity(41) }";
        let tokens = Lexer::new(source).tokenize().expect("lex");
        let file = Parser::new(tokens).parse_file().expect("parse");
        let checked = crate::core::check_program(&file).expect("check");
        let mut program = MirProgram::from_checked_program(&checked).expect("canonical MIR");
        crate::core::mir::validate_scalar_generic_identity_island(&program)
            .expect("valid scalar identity shape");

        let main = program
            .functions
            .get_mut(&NodeId("function:main".into()))
            .expect("main function");
        let constant = main
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
            .find(|instruction| {
                matches!(
                    &instruction.kind,
                    MirInstructionKind::Const {
                        literal: crate::core::ir::ResolvedLiteral::Int(_),
                        ..
                    }
                )
            })
            .expect("i32 argument constant");
        let MirInstructionKind::Const {
            literal: crate::core::ir::ResolvedLiteral::Int(value),
            ..
        } = &mut constant.kind
        else {
            unreachable!("filtered as integer constant")
        };
        *value = i64::from(i32::MAX) + 1;
        assert!(
            crate::core::mir::validate_scalar_generic_identity_island(&program).is_err(),
            "a forged MIR literal outside i32 range must not carry this profile"
        );
    }

    #[test]
    fn scalar_generic_identity_i64_island_rejects_forged_i32_abi_descriptor() {
        let source = "func identity<T>(value: T) -> T { value }\nfunc main() -> i64 { identity(2147483690) }";
        let tokens = Lexer::new(source).tokenize().expect("lex");
        let file = Parser::new(tokens).parse_file().expect("parse");
        let checked = crate::core::check_program(&file).expect("check");
        let mut program = MirProgram::from_checked_program(&checked).expect("canonical MIR");
        crate::core::mir::validate_scalar_generic_identity_i64_island(&program)
            .expect("valid scalar i64 identity shape");

        let argument = program
            .instances()
            .values()
            .next()
            .and_then(|instance| instance.arguments.first())
            .expect("i64 identity specialization argument")
            .clone();
        let mut descriptor = program
            .type_catalog()
            .get(&argument)
            .expect("i64 identity TypeDesc")
            .clone();
        descriptor.abi = super::super::types::MirAbiClass::Integer {
            bits: 32,
            signed: true,
        };
        program
            .type_catalog
            .replace_for_test_only(argument, descriptor);
        assert!(
            crate::core::mir::validate_scalar_generic_identity_i64_island(&program).is_err(),
            "a forged i32 ABI descriptor must not carry the i64 identity profile"
        );
    }

    #[test]
    fn concrete_scalar_generic_record_projection_is_canonical_and_borrowed() {
        let source =
            include_str!("../../../tests/fixtures/mir_native_generic_record_projection.mimi");
        let tokens = Lexer::new(source).tokenize().expect("lex");
        let file = Parser::new(tokens).parse_file().expect("parse");
        let checked = crate::core::check_program(&file).expect("check");
        let program = MirProgram::from_checked_program(&checked)
            .expect("generic record projection must materialize in canonical MIR");
        let instance = program
            .instances()
            .values()
            .next()
            .expect("generic record projection instance");
        let MirGenericInstanceContract::ScalarRecordProjection { contract } = &instance.contract
        else {
            panic!("generic record projection must carry a record receipt");
        };
        assert_eq!(contract.arity, 1);
        assert_eq!(contract.name, "value");
        let target = program
            .functions()
            .get(&instance.function)
            .expect("materialized generic record projection target");
        assert_eq!(contract.field_ty, target.result);
        let parameter_ty = target
            .parameters
            .first()
            .and_then(|parameter| target.values.get(parameter))
            .map(|value| value.ty.clone())
            .expect("record projection parameter TypeDesc");
        let parameter_desc = program
            .type_catalog()
            .get(&parameter_ty)
            .expect("record projection concrete TypeDesc");
        assert_eq!(
            parameter_desc.ownership,
            crate::core::mir::types::MirOwnership::Copy
        );
        assert_eq!(
            parameter_desc.abi,
            crate::core::mir::types::MirAbiClass::Aggregate
        );
        assert!(matches!(
            parameter_desc.layout,
            crate::core::mir::types::MirLayout::Record { ref fields, .. }
                if fields.len() == 1 && fields[0].ty == contract.field_ty
        ));
        assert!(target.canonical_text().contains("project"));
        let value = MirReferenceInterpreter::new(&program)
            .execute(&NodeId("function:main".into()), &[])
            .expect("reference generic record projection execution");
        assert_eq!(value, MirRuntimeValue::Int(41));
    }

