    #[test]
    fn canonical_program_gate_rejects_copy_only_switch_for_non_copy_variant() {
        let source = "func variant_probe() -> string { let value: Option<string> = Some(\"owned\"); match value { Some(v) => v, None => \"fallback\" } }\nfunc main() -> i32 { drop(variant_probe()); 0 }";
        let (_, program) = canonical_program_with_main(source);
        let owner = crate::core::NodeId("function:variant_probe".into());
        let mut function = program.functions().get(&owner).cloned().expect("main");
        let mut replaced = false;
        for block in function.blocks.values_mut() {
            let replacement = match &block.terminator {
                crate::core::mir::MirTerminator::SwitchMove { scrutinee, arms } => {
                    Some((scrutinee.clone(), arms.clone()))
                }
                _ => None,
            };
            if let Some((scrutinee, arms)) = replacement {
                block.terminator = crate::core::mir::MirTerminator::Switch { scrutinee, arms };
                replaced = true;
                break;
            }
        }
        assert!(replaced, "consuming variant switch");
        let errors = MirProgram::with_type_catalog(
            BTreeMap::from([(owner, function)]),
            program.type_catalog().clone(),
        )
        .expect_err("non-Copy variant must not use read-only Switch");
        assert!(
            errors.iter().any(|error| {
                error.message.contains("non-Copy") || error.message.contains("aggregate match glue")
            }),
            "{errors:?}"
        );
    }

    #[test]
    fn canonical_program_gate_rejects_missing_or_forged_ffi_receipt() {
        let source = r#"
extern "C" {
    func read(fd: i64) -> i64 requires: fd >= 0;
}
func caller(fd: i64) -> i64 { read(fd) }
func main() -> i64 { caller(0 as i64) }
"#;
        let tokens = Lexer::new(source).tokenize().expect("lex");
        let file = Parser::new(tokens).parse_file().expect("parse");
        let checked = crate::core::check_program(&file).expect("check");
        let canonical = MirProgram::from_checked_program(&checked).expect("canonical FFI MIR");
        let ffi_receipt = canonical.ffi_calls().values().next().expect("FFI receipt");
        assert_eq!(ffi_receipt.symbol, "read");
        assert_eq!(ffi_receipt.abi, "C");
        assert!(ffi_receipt.result.is_some());

        let missing = MirProgram::with_type_catalog_and_instances_and_transitions(
            canonical.functions().clone(),
            canonical.type_catalog().clone(),
            canonical.instances().clone(),
            canonical.transitions().clone(),
        )
        .expect_err("extern call without a receipt must fail before execution");
        assert!(
            missing
                .iter()
                .any(|error| error.message.contains("no canonical FFI contract")),
            "{missing:?}"
        );

        let mut forged_receipts = canonical.ffi_calls().clone();
        forged_receipts
            .values_mut()
            .next()
            .expect("FFI receipt")
            .callee = NodeId("extern:forged".into());
        let forged = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            canonical.functions().clone(),
            canonical.type_catalog().clone(),
            canonical.instances().clone(),
            canonical.transitions().clone(),
            forged_receipts,
        )
        .expect_err("forged extern identity must fail before execution");
        assert!(
            forged.iter().any(|error| {
                error
                    .message
                    .contains("FFI contract identity disagrees with MIR call")
            }),
            "{forged:?}"
        );

        let mut forged_abi = canonical.ffi_calls().clone();
        forged_abi.values_mut().next().expect("FFI receipt").abi = "Rust".into();
        let abi = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            canonical.functions().clone(),
            canonical.type_catalog().clone(),
            canonical.instances().clone(),
            canonical.transitions().clone(),
            forged_abi,
        )
        .expect_err("non-C FFI ABI must fail before execution");
        assert!(
            abi.iter()
                .any(|error| error.message.contains("outside the canonical C ABI")),
            "{abi:?}"
        );

        let mut forged_result = canonical.ffi_calls().clone();
        forged_result
            .values_mut()
            .next()
            .expect("FFI receipt")
            .result = Some(super::MirValueId::new("value:forged-result").expect("MIR value id"));
        let result = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            canonical.functions().clone(),
            canonical.type_catalog().clone(),
            canonical.instances().clone(),
            canonical.transitions().clone(),
            forged_result,
        )
        .expect_err("forged FFI result identity must fail before execution");
        assert!(
            result
                .iter()
                .any(|error| error.message.contains("FFI contract result disagrees")),
            "{result:?}"
        );
    }

    #[test]
    fn canonical_program_gate_rejects_ffi_call_metadata_outside_scalar_abi() {
        let source = r#"
extern "C" { func foreign(value: i64) -> i64; }
func main() -> i64 { foreign(1 as i64) }
"#;
        let (_, program) = canonical_program_with_main(source);
        let owner = NodeId("function:main".into());
        let mut functions = program.functions().clone();
        let function = functions.get_mut(&owner).expect("main MIR");
        let instruction = function
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
            .find(|instruction| {
                matches!(
                    instruction.kind,
                    MirInstructionKind::Call {
                        callee: ResolvedCallee::Extern(_),
                        ..
                    }
                )
            })
            .expect("extern call");
        let argument_type = match &instruction.kind {
            MirInstructionKind::Call { arguments, .. } => function
                .values
                .get(arguments.first().expect("extern argument"))
                .expect("extern argument TypeDesc")
                .ty
                .clone(),
            _ => unreachable!(),
        };
        let MirInstructionKind::Call { type_arguments, .. } = &mut instruction.kind else {
            unreachable!();
        };
        type_arguments.push(argument_type);
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            functions,
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            program.ffi_calls().clone(),
        )
        .expect_err("extern generic metadata must fail before consumers");
        assert!(
            errors.iter().any(|error| {
                error
                    .message
                    .contains("canonical scalar FFI call cannot have type arguments")
            }),
            "{errors:?}"
        );

        let mut functions = program.functions().clone();
        let function = functions.get_mut(&owner).expect("main MIR");
        let instruction = function
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
            .find(|instruction| {
                matches!(
                    instruction.kind,
                    MirInstructionKind::Call {
                        callee: ResolvedCallee::Extern(_),
                        ..
                    }
                )
            })
            .expect("extern call");
        let (callee, argument_type, result_type) = match &instruction.kind {
            MirInstructionKind::Call {
                callee: ResolvedCallee::Extern(callee),
                arguments,
                result: Some(result),
                ..
            } => (
                callee.clone(),
                function
                    .values
                    .get(arguments.first().expect("extern argument"))
                    .expect("argument TypeDesc")
                    .ty
                    .clone(),
                function
                    .values
                    .get(result)
                    .expect("result TypeDesc")
                    .ty
                    .clone(),
            ),
            _ => unreachable!(),
        };
        let MirInstructionKind::Call {
            variant_call_contract,
            ..
        } = &mut instruction.kind
        else {
            unreachable!();
        };
        *variant_call_contract = Some(crate::core::mir::types::MirVariantCallAbiContract {
            callee,
            type_arguments: Vec::new(),
            parameter_types: vec![argument_type.clone()],
            result_ty: result_type.clone(),
            mode: crate::core::mir::types::MirVariantCallAbiMode::FlatCopy,
            return_mode: crate::core::mir::types::MirVariantCallReturnMode::FlatCopyMerge,
            payload_ty: argument_type.clone(),
            payload_types: vec![argument_type],
            nominal: crate::core::ir::NominalTypeId::new("builtin:type:Option")
                .expect("Option nominal"),
            variants: Vec::new(),
        });
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            functions,
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            program.ffi_calls().clone(),
        )
        .expect_err("extern variant metadata must fail before consumers");
        assert!(
            errors.iter().any(|error| {
                error
                    .message
                    .contains("canonical scalar FFI call cannot carry a variant ABI receipt")
            }),
            "{errors:?}"
        );
    }

    #[test]
    fn canonical_program_gate_rejects_ffi_result_and_symbol_identity_gaps() {
        let source = r#"
extern "C" { func foreign(value: i64) -> i64; }
func main() -> i64 { foreign(1 as i64); 0 }
"#;
        let (_, program) = canonical_program_with_main(source);
        let owner = NodeId("function:main".into());
        let instruction_id = program
            .ffi_calls()
            .keys()
            .next()
            .cloned()
            .expect("FFI receipt");
        let mut functions = program.functions().clone();
        let function = functions.get_mut(&owner).expect("main MIR");
        let instruction = function
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
            .find(|instruction| instruction.id == instruction_id)
            .expect("extern call");
        let old_result = match &instruction.kind {
            MirInstructionKind::Call { result, .. } => result.clone(),
            _ => unreachable!(),
        };
        let MirInstructionKind::Call { result, .. } = &mut instruction.kind else {
            unreachable!();
        };
        *result = None;
        if let Some(old_result) = old_result {
            function.values.remove(&old_result);
            function
                .ownership
                .events
                .retain(|event| event.value.as_ref() != Some(&old_result));
        }
        let mut receipts = program.ffi_calls().clone();
        receipts
            .get_mut(&instruction_id)
            .expect("FFI receipt")
            .result = None;
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            functions,
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("extern calls must retain a canonical result identity");
        assert!(
            errors.iter().any(|error| {
                error
                    .message
                    .contains("extern call has no canonical result value identity")
            }),
            "{errors:?}"
        );

        let (_, program) = canonical_program_with_main(
            "extern \"C\" { func foreign(value: i64) -> i64; } func main() -> i64 { foreign(1 as i64) }",
        );
        let mut receipts = program.ffi_calls().clone();
        receipts.values_mut().next().expect("FFI receipt").symbol = "foreign\0symbol".into();
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("C symbol control characters must fail before consumers");
        assert!(
            errors.iter().any(|error| {
                error.message.contains("FFI symbol is not manifest-safe")
                    && error.message.contains("control character")
            }),
            "{errors:?}"
        );

        for (symbol, reason) in [
            ("foreign symbol", "whitespace or a manifest delimiter"),
            ("foreign=symbol", "whitespace or a manifest delimiter"),
            ("foreign,symbol", "whitespace or a manifest delimiter"),
            (
                "mimi_mir_map_root_contains",
                "reserved Canonical MIR MapRoot runtime helper",
            ),
            (
                "mimi_mir_actor_domain_claim_root",
                "reserved Canonical MIR ActorExecutionDomain runtime helper",
            ),
        ] {
            let (_, program) = canonical_program_with_main(
                "extern \"C\" { func foreign(value: i64) -> i64; } func main() -> i64 { foreign(1 as i64) }",
            );
            let mut receipts = program.ffi_calls().clone();
            receipts.values_mut().next().expect("FFI receipt").symbol = symbol.into();
            let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
                program.functions().clone(),
                program.type_catalog().clone(),
                program.instances().clone(),
                program.transitions().clone(),
                receipts,
            )
            .expect_err("manifest-ambiguous C symbols must fail before consumers");
            assert!(
                errors.iter().any(|error| {
                    error.message.contains("FFI symbol is not manifest-safe")
                        && error.message.contains(reason)
                }),
                "{symbol}: {errors:?}"
            );
        }

        let (_, program) = canonical_program_with_main(
            "extern \"C\" { func foreign(value: i64) -> i64; } func main() -> i64 { foreign(1 as i64) }",
        );
        let mut receipts = program.ffi_calls().clone();
        receipts.values_mut().next().expect("FFI receipt").symbol = "safe_other".into();
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("safe but mismatched C symbols must fail at MIR admission");
        assert!(
            errors.iter().any(|error| error
                .message
                .contains("symbol disagrees with canonical extern callee")),
            "{errors:?}"
        );

        let (_, program) = canonical_program_with_main(
            "extern \"C\" { func foreign(value: i64) -> i64; } func main() -> i64 { foreign(1 as i64) }",
        );
        let instruction_id = program
            .ffi_calls()
            .keys()
            .next()
            .cloned()
            .expect("FFI receipt");
        let original_callee = program
            .ffi_calls()
            .get(&instruction_id)
            .expect("FFI receipt")
            .callee
            .clone();
        let rust_callee = NodeId(original_callee.0.replacen("extern:C:", "extern:Rust:", 1));
        let mut functions = program.functions().clone();
        let main = functions
            .get_mut(&NodeId("function:main".into()))
            .expect("main MIR");
        let call = main
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
            .find(|instruction| instruction.id == instruction_id)
            .expect("extern call");
        if let MirInstructionKind::Call { callee, .. } = &mut call.kind {
            *callee = ResolvedCallee::Extern(rust_callee.clone());
        }
        let mut receipts = program.ffi_calls().clone();
        receipts
            .get_mut(&instruction_id)
            .expect("FFI receipt")
            .callee = rust_callee;
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            functions,
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("non-C extern owners must fail at MIR admission");
        assert!(
            errors
                .iter()
                .any(|error| error.message.contains("outside the canonical C ABI")),
            "{errors:?}"
        );
    }

    #[test]
    fn ffi_source_witness_rejects_same_node_mir_argument_value_substitution() {
        let (_, program) = canonical_program_with_main(
            r#"
extern "C" { func foreign(value: i32) -> i32; }
func main() -> i32 { foreign(1) }
"#,
        );
        let receipt = program.ffi_calls().values().next().expect("FFI receipt");
        let mut function = program
            .functions()
            .get(&receipt.caller)
            .cloned()
            .expect("caller MIR");
        let argument = receipt.arguments.first().expect("one call argument");
        let literal = function
            .blocks
            .values_mut()
            .flat_map(|block| block.instructions.iter_mut())
            .find_map(|instruction| match &mut instruction.kind {
                MirInstructionKind::Const {
                    result,
                    literal: crate::core::ResolvedLiteral::Int(value),
                } if result == argument => Some(value),
                _ => None,
            })
            .expect("the argument is a direct integer literal");
        *literal = 2;

        let errors = crate::core::mir::validate_ffi_call_contract_receipt(
            program.type_catalog(),
            &function,
            &receipt.instruction,
            &receipt.callee,
            receipt.result.as_ref(),
            &receipt.arguments,
            receipt,
        );
        assert!(
            errors
                .iter()
                .any(|message| { message.contains("checked-source witness disagrees") }),
            "same-NodeId payload tampering must invalidate the private source seal: {errors:?}"
        );
    }

    #[test]
    fn canonical_variadic_ffi_receipt_carries_source_and_promoted_types() {
        let (_, program) = canonical_program_with_main(
            r#"
extern "C" { func foreign(head: i32 ...) -> i32; }
func main() -> i32 {
    let flag: bool = true
    let flag2: bool = false
    let sample: f32 = 1.25 as f32
    foreign(7, flag, flag2, sample)
}
"#,
        );
        let receipt = program.ffi_calls().values().next().expect("FFI receipt");
        assert_eq!(receipt.fixed_argument_count, 1);
        assert!(receipt.variadic);
        assert_eq!(receipt.arguments.len(), 4);
        assert_eq!(receipt.variadic_arguments.len(), 3);
        assert_eq!(
            receipt
                .variadic_arguments
                .iter()
                .map(|tail| tail.promotion)
                .collect::<Vec<_>>(),
            vec![
                MirFfiDefaultPromotion::IntegerToI32,
                MirFfiDefaultPromotion::IntegerToI32,
                MirFfiDefaultPromotion::FloatToF64,
            ]
        );
        let promoted_kinds = receipt
            .variadic_arguments
            .iter()
            .map(|tail| {
                program
                    .type_catalog()
                    .get(&tail.promoted_type)
                    .expect("promoted TypeDesc")
                    .kind
                    .clone()
            })
            .collect::<Vec<_>>();
        assert_eq!(
            promoted_kinds,
            vec![
                MirTypeKind::Primitive(crate::core::ir::PrimitiveType::I32),
                MirTypeKind::Primitive(crate::core::ir::PrimitiveType::I32),
                MirTypeKind::Primitive(crate::core::ir::PrimitiveType::F64),
            ]
        );
        for (tail_offset, tail) in receipt.variadic_arguments.iter().enumerate() {
            let index = receipt.fixed_argument_count + tail_offset;
            assert_eq!(tail.argument_index, index);
            assert_eq!(
                receipt.arguments[index].as_str(),
                format!("expr:{}", tail.source_node.0)
            );
        }
    }

    #[test]
    fn forged_ffi_symbol_is_rejected_by_every_direct_consumer() {
        const SOURCE_METADATA_MISMATCH: &str =
            "checked extern declaration ABI/contract metadata differs";

        for symbol in [
            "foreign symbol",
            "mimi_mir_map_root_contains",
            "mimi_mir_actor_domain_claim_root",
        ] {
            let (_, program) = canonical_program_with_main(
                "extern \"C\" { func foreign(value: i64) -> i64; } func main() -> i64 { foreign(1 as i64) }",
            );
            let mut receipts = program.ffi_calls().clone();
            receipts.values_mut().next().expect("FFI receipt").symbol = symbol.into();
            let mut forged = program;
            forged.replace_ffi_calls_for_test_only(receipts);

            let reference_error = MirReferenceInterpreter::new(&forged)
                .execute(&NodeId("function:main".into()), &[])
                .expect_err("reference must reject forged source metadata before resolution");
            assert!(
                reference_error
                    .to_string()
                    .contains(SOURCE_METADATA_MISMATCH),
                "{reference_error}"
            );

            let bytecode_error = crate::interp::bytecode::compile_mir_program(&forged)
                .expect_err("bytecode must reject a forged manifest-unsafe symbol");
            let expected_symbol_diagnostic = match symbol {
                "foreign symbol" => "FFI symbol contains whitespace or a manifest delimiter",
                "mimi_mir_map_root_contains" => "reserved Canonical MIR MapRoot runtime helper",
                "mimi_mir_actor_domain_claim_root" => {
                    "reserved Canonical MIR ActorExecutionDomain runtime helper"
                }
                _ => unreachable!("covered forged symbol"),
            };
            assert!(
                bytecode_error.iter().any(|error| {
                    error.message.contains("FFI symbol is not manifest-safe")
                        && error.message.contains(expected_symbol_diagnostic)
                }),
                "{bytecode_error:?}"
            );

            let native_error = crate::codegen::mir::validate_mir_native(&forged)
                .expect_err("native validator must reject a forged manifest-unsafe symbol");
            assert!(
                native_error
                    .iter()
                    .any(|error| { error.message.contains(SOURCE_METADATA_MISMATCH) }),
                "{native_error:?}"
            );

            let capability_error = crate::verifier::validate_mir_capabilities(&forged)
                .expect_err("verifier capability gate must reject a forged symbol");
            assert!(
                capability_error.iter().any(|error| {
                    error.contains("FFI symbol is not manifest-safe")
                        && error.contains(expected_symbol_diagnostic)
                }),
                "{capability_error:?}"
            );

            let verifier_error = crate::verifier::verify_mir(&forged, "forged-symbol".into())
                .expect_err("direct verifier must reject a forged symbol even without obligations");
            assert!(
                verifier_error.contains(SOURCE_METADATA_MISMATCH),
                "{verifier_error}"
            );
        }
    }

    #[test]
    fn forged_ffi_abi_is_rejected_by_every_direct_consumer() {
        let (_, program) = canonical_program_with_main(
            "extern \"C\" { func foreign(value: i64) -> i64; } func main() -> i64 { foreign(1 as i64) }",
        );
        let mut receipts = program.ffi_calls().clone();
        receipts.values_mut().next().expect("FFI receipt").abi = "Rust".into();
        let mut forged = program;
        forged.replace_ffi_calls_for_test_only(receipts);

        let reference_error = MirReferenceInterpreter::new(&forged)
            .execute(&NodeId("function:main".into()), &[])
            .expect_err("reference must reject a forged non-C ABI");
        assert!(
            reference_error
                .to_string()
                .contains("FFI receipt disagrees with the MIR call")
                || reference_error.to_string().contains("receipt ABI")
        );

        let bytecode_error = crate::interp::bytecode::compile_mir_program(&forged)
            .expect_err("bytecode must reject a forged non-C ABI");
        assert!(bytecode_error.iter().any(|error| {
            error.message.contains("identity/ABI validation")
                || error.message.contains("outside the canonical C ABI")
        }));

        let native_error = crate::codegen::mir::validate_mir_native(&forged)
            .expect_err("native validator must reject a forged non-C ABI");
        assert!(native_error
            .iter()
            .any(|error| error.message.contains("FFI ABI 'Rust'")));

        let capability_error = crate::verifier::validate_mir_capabilities(&forged)
            .expect_err("verifier capability gate must reject a forged non-C ABI");
        assert!(capability_error
            .iter()
            .any(|error| error.contains("outside the canonical C ABI")));

        let verifier_error = crate::verifier::verify_mir(&forged, "forged-abi".into())
            .expect_err("direct verifier must reject a forged non-C ABI without obligations");
        assert!(verifier_error.contains("ABI 'Rust' is outside the canonical C ABI"));
    }

    #[test]
    fn forged_ffi_symbol_declaration_shape_is_rejected_by_every_direct_consumer() {
        let (_, program) = canonical_program_with_main(
            r#"
extern "C" { func foreign(value: i64) -> i64; }
func main() -> i64 {
    let narrow = foreign(7 as i32);
    let wide = foreign(8 as i64);
    narrow + wide
}
"#,
        );
        assert_eq!(program.ffi_calls().len(), 2);
        let main = program
            .functions()
            .get(&NodeId("function:main".into()))
            .expect("main MIR");
        let (second_id, second_argument) = program
            .ffi_calls()
            .iter()
            .find_map(|(id, receipt)| {
                let argument = receipt.arguments.first()?;
                let actual = main.values.get(argument)?;
                (actual.ty != receipt.parameter_types[0]).then(|| (id.clone(), argument.clone()))
            })
            .expect("mixed-width FFI receipt");
        let actual_type = main
            .values
            .get(&second_argument)
            .map(|value| value.ty.clone())
            .expect("second argument TypeDesc");

        let mut receipts = program.ffi_calls().clone();
        let forged_receipt = receipts.get_mut(&second_id).expect("second receipt");
        forged_receipt.parameter_types[0] = actual_type.clone();
        forged_receipt.parameter_conversions[0] =
            MirFfiAbiConversion::for_argument(program.type_catalog(), &actual_type, &actual_type)
                .expect("identity conversion");
        let mut forged = program;
        forged.replace_ffi_calls_for_test_only(receipts);

        let reference_error = MirReferenceInterpreter::new(&forged)
            .execute(&NodeId("function:main".into()), &[])
            .expect_err("reference must reject divergent FFI declaration shapes");
        assert!(reference_error
            .to_string()
            .contains("incompatible declaration TypeDescs"));

        let bytecode_error = crate::interp::bytecode::compile_mir_program(&forged)
            .expect_err("bytecode must reject divergent FFI declaration shapes");
        assert!(bytecode_error
            .iter()
            .any(|error| error.message.contains("incompatible declaration TypeDescs")));

        let native_error = crate::codegen::mir::validate_mir_native(&forged)
            .expect_err("native validator must reject divergent FFI declaration shapes");
        assert!(native_error
            .iter()
            .any(|error| error.message.contains("incompatible declaration TypeDescs")));

        let capability_error = crate::verifier::validate_mir_capabilities(&forged)
            .expect_err("capability gate must reject divergent FFI declaration shapes");
        assert!(capability_error
            .iter()
            .any(|error| error.contains("incompatible declaration TypeDescs")));

        let verifier_error = crate::verifier::verify_mir(&forged, "forged-ffi-shape".into())
            .expect_err("direct verifier must reject divergent FFI declaration shapes");
        assert!(verifier_error.contains("incompatible declaration TypeDescs"));
    }

    #[test]
    fn forged_ffi_endpoint_metadata_is_rejected_by_every_direct_consumer() {
        let (_, program) = canonical_program_with_main(
            "extern \"C\" { func foreign(value: i64) -> i64; } func main() -> i64 { foreign(1 as i64) }",
        );
        let receipt = program.ffi_calls().values().next().expect("FFI receipt");
        let scalar_id = receipt
            .parameter_types
            .first()
            .expect("FFI parameter TypeDesc")
            .clone();
        let mut descriptor = program
            .type_catalog()
            .get(&scalar_id)
            .expect("scalar TypeDesc")
            .clone();
        descriptor.session_protocol = Some(scalar_id.clone());
        let mut catalog = program.type_catalog().clone();
        catalog.replace_for_test_only(scalar_id, descriptor);
        let forged = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            catalog,
            program.instances().clone(),
            program.transitions().clone(),
            program.ffi_calls().clone(),
        )
        .expect("MIR boundary retains a forged endpoint for consumer gates");

        let reference_error = MirReferenceInterpreter::new(&forged)
            .execute(&NodeId("function:main".into()), &[])
            .expect_err("reference must reject forged endpoint metadata");
        assert_eq!(
            reference_error.diagnostic_code(),
            Some(crate::core::mir::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE)
        );
        assert!(
            reference_error
                .to_string()
                .contains("complete scalar endpoint contract"),
            "{reference_error}"
        );

        let bytecode_error = crate::interp::bytecode::compile_mir_program(&forged)
            .expect_err("bytecode must reject forged endpoint metadata");
        assert!(bytecode_error.iter().any(|error| {
            error.diagnostic_code()
                == Some(crate::core::mir::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE)
                && (error.message.contains("complete scalar endpoint contract")
                    || error.message.contains("complete Copy scalar shape"))
        }));

        let native_error = crate::codegen::mir::validate_mir_native(&forged)
            .expect_err("native must reject forged endpoint metadata");
        assert!(native_error.iter().any(|error| {
            error.code.as_deref() == Some(crate::core::mir::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE)
                && error.message.contains("complete scalar endpoint contract")
        }));

        let capability_error = crate::verifier::validate_mir_capabilities(&forged)
            .expect_err("verifier capability gate must reject forged endpoint metadata");
        assert!(capability_error.iter().any(|error| {
            error.contains(crate::core::mir::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE)
                && error.contains("complete scalar endpoint contract")
        }));

        let verifier_error = crate::verifier::verify_mir(&forged, "forged-ffi-endpoint".into())
            .expect_err("verifier must reject forged endpoint metadata");
        assert!(
            verifier_error.contains(crate::core::mir::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE)
                && verifier_error.contains("complete scalar endpoint contract"),
            "{verifier_error}"
        );
    }

    #[test]
    fn forged_ffi_conversion_receipt_is_rejected_by_every_direct_consumer() {
        let (_, program) = canonical_program_with_main(
            "extern \"C\" { func foreign(value: i64) -> i32; } func main() -> i32 { foreign(1 as i64) }",
        );
        let receipt = program.ffi_calls().values().next().expect("FFI receipt");
        assert_eq!(receipt.parameter_conversions.len(), 1);
        assert!(receipt.result_conversion.is_some());

        for mutation in 0..2 {
            let mut receipts = program.ffi_calls().clone();
            let forged = receipts.values_mut().next().expect("FFI receipt");
            if mutation == 0 {
                forged.parameter_conversions[0] = MirFfiAbiConversion {
                    from: crate::core::mir::types::MirAbiClass::Integer {
                        bits: 32,
                        signed: true,
                    },
                    to: crate::core::mir::types::MirAbiClass::Integer {
                        bits: 64,
                        signed: true,
                    },
                };
            } else {
                forged.result_conversion = Some(MirFfiAbiConversion {
                    from: crate::core::mir::types::MirAbiClass::Integer {
                        bits: 64,
                        signed: true,
                    },
                    to: crate::core::mir::types::MirAbiClass::Integer {
                        bits: 32,
                        signed: true,
                    },
                });
            }
            let mut forged_program = program.clone();
            forged_program.replace_ffi_calls_for_test_only(receipts);

            let reference_error = MirReferenceInterpreter::new(&forged_program)
                .execute(&NodeId("function:main".into()), &[])
                .expect_err("reference must reject forged conversion receipt");
            assert!(
                reference_error
                    .to_string()
                    .contains("conversion receipt disagrees")
                    || reference_error.to_string().contains("conversion from"),
                "{reference_error}"
            );

            let bytecode_error = crate::interp::bytecode::compile_mir_program(&forged_program)
                .expect_err("bytecode must reject forged conversion receipt");
            assert!(bytecode_error.iter().any(|error| {
                error.message.contains("conversion receipt disagrees")
                    || error.message.contains("conversion from")
            }));

            let native_error = crate::codegen::mir::validate_mir_native(&forged_program)
                .expect_err("native must reject forged conversion receipt");
            assert!(native_error.iter().any(|error| {
                error.message.contains("conversion receipt disagrees")
                    || error.message.contains("conversion from")
            }));

            let capability_error = crate::verifier::validate_mir_capabilities(&forged_program)
                .expect_err("verifier capability gate must reject forged conversion receipt");
            assert!(capability_error.iter().any(|error| {
                error.contains("conversion receipt disagrees") || error.contains("conversion from")
            }));

            let verifier_error =
                crate::verifier::verify_mir(&forged_program, "forged-ffi-conversion".into())
                    .expect_err("verifier must reject forged conversion receipt");
            assert!(
                verifier_error.contains("conversion receipt disagrees")
                    || verifier_error.contains("conversion from"),
                "{verifier_error}"
            );
        }
    }

    #[test]
    fn canonical_program_gate_rejects_orphaned_ffi_receipts() {
        let source = "extern \"C\" { func foreign(value: i64) -> i64; } func main() -> i64 { foreign(1 as i64) }";
        let (_, program) = canonical_program_with_main(source);
        let receipt = program
            .ffi_calls()
            .values()
            .next()
            .cloned()
            .expect("FFI receipt");
        let orphan_instruction =
            crate::core::mir::MirInstructionId::new("inst:call:orphan").expect("instruction id");
        let mut orphan = receipt;
        orphan.instruction = orphan_instruction.clone();
        let mut receipts = program.ffi_calls().clone();
        receipts.insert(orphan_instruction, orphan);
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("orphaned FFI receipts must fail before consumers");
        assert!(
            errors.iter().any(|error| {
                error
                    .message
                    .contains("canonical FFI contract is orphaned from a MIR extern call")
            }),
            "{errors:?}"
        );

        let (_, program) = canonical_program_with_main(source);
        let forged_argument = super::MirValueId::new("value:forged-argument").expect("value id");
        let instruction_id = program
            .ffi_calls()
            .keys()
            .next()
            .cloned()
            .expect("FFI instruction");
        let mut receipts = program.ffi_calls().clone();
        receipts
            .get_mut(&instruction_id)
            .expect("FFI receipt")
            .arguments = vec![forged_argument];
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("FFI value identities must be declared by the caller MIR function");
        assert!(
            errors.iter().any(|error| {
                error
                    .message
                    .contains("FFI contract argument 0 value identity is absent")
            }),
            "{errors:?}"
        );

        let (_, program) = canonical_program_with_main(source);
        let bool_type = program
            .type_catalog()
            .iter()
            .find_map(|(id, descriptor)| {
                matches!(descriptor.abi, crate::core::mir::types::MirAbiClass::Bool)
                    .then(|| id.clone())
            })
            .expect("bool TypeDesc");
        let instruction_id = program
            .ffi_calls()
            .keys()
            .next()
            .cloned()
            .expect("FFI instruction");
        let mut receipts = program.ffi_calls().clone();
        receipts
            .get_mut(&instruction_id)
            .expect("FFI receipt")
            .parameter_types = vec![bool_type.clone()];
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("FFI declaration and MIR argument TypeDescs must agree");
        assert!(
            errors.iter().any(|error| {
                error
                    .message
                    .contains("FFI declaration parameter 0 TypeDesc disagrees with MIR argument")
            }),
            "{errors:?}"
        );

        let mut receipts = program.ffi_calls().clone();
        receipts
            .get_mut(&instruction_id)
            .expect("FFI receipt")
            .parameter_types
            .clear();
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("FFI declaration parameter arity must be represented in the receipt");
        assert!(
            errors.iter().any(|error| {
                error.message.contains(
                    "extern call FFI physical parameter TypeDesc count disagrees with MIR arguments",
                )
            }),
            "{errors:?}"
        );

        let mut receipts = program.ffi_calls().clone();
        receipts
            .get_mut(&instruction_id)
            .expect("FFI receipt")
            .result_type = bool_type;
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("FFI declaration result TypeDesc must agree with MIR result");
        assert!(
            errors.iter().any(|error| {
                error.message.contains(
                    "extern call FFI declaration result TypeDesc disagrees with MIR result",
                )
            }),
            "{errors:?}"
        );
    }

