    static ORDINARY_MAP_NEW_RESULT_STATUS: std::cell::Cell<Option<i32>> = const { std::cell::Cell::new(None) };
    static ORDINARY_MAP_SET_RESULT_STATUS: std::cell::Cell<Option<i32>> = const { std::cell::Cell::new(None) };
